    "description": "Enable roaming for line L1001 associated with customer C1001."
  },
  "applicable_norms": [
    {
      "policy_source_id": "q4",
      "interpretation": "The assistant must not perform actions outside the scope of its declared capabilities (technical support, overdue bill payment, line suspension, plan options).",
      "modality": "FORBID"
    },
    {
      "policy_source_id": "q4",
      "interpretation": "The assistant must only make one tool call at a time and cannot respond to the user simultaneously.",
      "modality": "REQUIRE"
    },
    {
      "policy_source_id": "q6",
      "interpretation": "If a user is traveling outside their home network and the line is not roaming-enabled, the assistant should enable roaming at no cost for the user.",
      "modality": "REQUIRE"
    },
    {
      "policy_source_id": "q11",
      "interpretation": "If the user is experiencing data issues while roaming, the assistant should check and enable roaming if it is not already enabled.",
      "modality": "REQUIRE"
    },
    {
      "policy_source_id": "q12",
      "interpretation": "The assistant must ensure that all actions taken are within the scope of the user's request and the policy guidelines.",
      "modality": "REQUIRE"
    },
    {
      "policy_source_id": "q10",
      "interpretation": "The assistant must troubleshoot mobile data issues before enabling additional services like roaming.",
      "modality": "REQUIRE"
    }
  ],
  "supporting_evidence": [
    {
      "source_id": "h2",
      "actor": "user",
      "role": "customer",
      "fact": "User reported mobile data issues while abroad in France, requiring excellent internet speed."
    },
    {
      "source_id": "h4",
      "actor": "user",
      "role": "customer",
      "fact": "User confirmed the phone number 555-123-2002 is being used for mobile data in France."
    },
    {
      "source_id": "h10",
      "actor": "assistant",
      "role": "system",
      "fact": "Line L1001 (phone number 555-123-2001) has roaming_enabled set to false."
    },
    {
      "source_id": "q13",
      "actor": "system",
      "role": "tool_declaration",
      "fact": "Tool enable_roaming is declared and can be used to enable international roaming on a line."
    },
    {
      "source_id": "q6",
      "actor": "system",
      "role": "policy",
      "fact": "Roaming should be enabled at no cost for users traveling outside their home network if not already enabled."
    }
  ],
  "exception_analysis": "No exceptions apply. The user's request aligns with the policy to enable roaming for data connectivity issues while abroad, and the tool is explicitly declared for this purpose.",
  "reason": "The current action (enabling roaming for line L1001) is **REQUIRED** under **q6** and **q11** due to the user's reported mobile data issues while abroad. The line's roaming status is confirmed as disabled (**h10**), and the tool **enable_roaming** is declared (**q13**). The action adheres to the policy of enabling roaming at no cost for users outside their home network (**q6**). No violations of prohibitions or additional requirements are observed.",
